Q: Jquery Datatables Date Range Filter A: <p>I don't know if helps but i do the thing you ask like this</p>

<p><strong>EDIT</strong></p>

<p>Here more explanation. The $.fn.DataTable.ext.search it's the API provided for Datatables to extend the functions of filtering. First there is an array wich has the names of the tables who has to apply the function below (this is in case there is more than one table on the same page), then gets the value from de datepickers and split for create another Date who has the same format in the three cases (From, To and StartDate). Then compares that dates between them and filter as appropiate. The StartDate is from the current record of the Table.</p>

<p>At the datepickers i added the class <strong>date-range-filter</strong></p>

<pre><code>var allowFilter = ['tableOT'];

$('.date-range-filter').change(function() {
            oTable.draw();
        });

$.fn.dataTable.ext.search.push(
      function(settings, data, dataIndex) {
          // check if current table is part of the allow list
          if ( $.inArray( settings.nTable.getAttribute('id'), allowFilter ) == -1 )
          {
              // if not table should be ignored
              return true;
          }
          var min = $("#&lt;%=txtFechaDesde.ClientID %&gt;").val();
          var max = $("#&lt;%=txtFechaHasta.ClientID %&gt;").val();
          var fromDate;
          var toDate;
          // need to change str order before making  date obect since it uses a new Date("mm/dd/yyyy") format for short date.
          var d = data[0].split("/");
          var startDate = new Date(d[1]+ "/" +  d[0] +"/" + d[2]);
          if(min != ""){
              var fd = min.split("/");
              fromDate =  new Date(fd[1]+ "/" +  fd[0] +"/" + fd[2]);
          }
          if(max != ""){
              var td = max.split("/");
              toDate =  new Date(td[1]+ "/" +  td[0] +"/" + td[2]);
          }

          if (fromDate == null &amp;&amp; toDate == null) { return true; }
          if (fromDate == null &amp;&amp; startDate &lt;= toDate) { return true;}
          if(toDate == null &amp;&amp; startDate &gt;= fromDate) {return true;}
          if (startDate &lt;= toDate &amp;&amp; startDate &gt;= fromDate) { return true; }
          return false;
      }
    );
</code></pre>
